const summary=()=>{const t=data.latest;return lang==='hi'?`${data.last} के आंकड़े। कुल बिक्री ${rupee(t.total)}। नकद ${rupee(t.cash)}। यूपीआई ${rupee(t.upi)}। नया उधार ${rupee(t.credit)}। यह बकाया उधार की कुल राशि नहीं है।`:lang==='mr'?`${data.last} चे आकडे. एकूण विक्री ${rupee(t.total)}. रोख ${rupee(t.cash)}. यूपीआय ${rupee(t.upi)}. नवीन उधार ${rupee(t.credit)}. ही एकूण थकबाकी नाही.`:`For ${data.last}, sales were ${rupee(t.total)}. Cash ${rupee(t.cash)}, UPI ${rupee(t.upi)}, and new credit ${rupee(t.credit)}. New credit is not your total outstanding balance.`};
